    \node at (58,13) {その他};
    \fill[PaleGreen,draw=Secondary] (48,25) rectangle (68,60);
    \node at (58,43) {空調};
    \fill[PaleOrange,draw=Accent] (48,60) rectangle (68,75);
    \node at (58,68) {照明};
    \node[below] at (58,-3) {施策ケース};
